def partner_page(slug, name, short, heading, subhead, about_head, about_body, about_bullets, how_head, how_body, how_bullets,
                 benefits, benefits_head, link_items, link_head, faq, contact_bullets, contact_head, image=None, image_alt=None, crumbs_name=None, hero_label=None):
    site = PARTNER_LINKS[slug]
    hero = {"type": "hero", "layout": "split", "eyebrow": f"Technology partner: {name}", "heading": heading, "subhead": subhead,
            "primary": {"label": hero_label or f"Visit {name}", "href": site}, "secondary": {"label": "All technology partners", "href": "partners.html"}}
    if image:
        hero.update({"image": image, "image_alt": image_alt, "image_w": 1200, "image_h": 800})
    secs = [
        hero,
        {"type": "detail", "alt": True, "eyebrow": f"About {name}", "heading": about_head, "body": about_body, "bullets": about_bullets},
        {"type": "detail", "eyebrow": "How the integration works", "heading": how_head, "body": how_body, "bullets": how_bullets, "flip": True},
        {"type": "cards", "alt": True, "eyebrow": f"What {short} does for a DMP dealer", "heading": benefits_head, "items": benefits},
        {"type": "services", "heading": link_head, "intro": "Each links to the page for that product or system.", "items": link_items},
        {"type": "faq", "heading": f"Questions about {short} and DMP", "items": faq},
        {"type": "detail", "alt": True, "eyebrow": "Next step", "heading": contact_head, "body": "Reach the partner directly for integration specifications, setup help and partnership questions.", "bullets": contact_bullets},
        LEADFORM,
    ]
    return {"file": f"partners/{slug}.html", "title": title(f"{name} integration"),
            "description": desc(f"{name} with DMP: {subhead}"),
            "crumbs": [["Home", "index.html"], ["Technology partners", "partners.html"], [crumbs_name or name, f"partners/{slug}.html"]],
            "sections": secs}


